pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle).
    // We want to minimize post_residual, but we need to account for the impact on future placements.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we want to be more conservative about opening new bins.
    if is_new_bin {
        score += 15.0 + (progress * 25.0);
    }

    // Lookahead logic:
    // If we have a next item, penalize bins that leave a post_residual 
    // that is too small to fit the next item (creating "dead space").
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating unfillable space, scaled by how much of the capacity is wasted.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly enough space for the next item (or close to it).
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Heuristic pressure based on fitting_bins_count:
    // If this is the only bin that fits, we are forced to take it, but we can 
    // adjust the score to reflect the "tightness" of the fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0; 
    }

    // Non-linear coupling: 
    // Balance the mean residual of the system. If the current bin's post_residual 
    // is significantly better than the mean, prioritize it.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #141: Harmonic-Residual Coupling
    // We prioritize bins that result in "harmonic" residuals (multiples of common divisors)
    // while penalizing the creation of a new bin unless the current mean residual is too tight.

    let mut score = post_residual as f64;

    // 1. Penalty for creating a new bin if other options exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 2. Harmonic logic: Reward post-residuals that are multiples of 10 or 25 (common packing divisors)
    // This encourages "clean" remaining space for future items.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // 3. Lookahead coupling: If the next item is large, avoid small post_residuals (dead space)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for creating a "stranded" bin that cannot fit the next item
            score += 20.0;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward "tight but sufficient" fits for the next item
            score -= 12.0;
        }
    }

    // 4. Density normalization: As the stream progresses, prioritize closing bins (lower residual)
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.2;

    // 5. If this is the last chance to fit the item, discount the score to prefer existing bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    // We penalize bins that leave very small gaps (e.g., < 5) which are hard to fill
    let fragmentation_penalty = if post < 5.0 && post > 0.0 {
        15.0 / (post + 1.0)
    } else {
        0.0
    };

    // Lookahead: If the next item is large, favor bins that leave enough space for it
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Global state awareness: 
    // As the stream progresses, become more aggressive in packing tightly
    // to prevent leaving too many bins open.
    let density_pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)) * 2.0;

    // Decision logic for NEW bin:
    // If we are forced to create a new bin (bin_residual == bin_capacity), 
    // we return a score that is compared against existing fits.
    let is_new_bin = bin_residual == bin_capacity;
    let base_score = if is_new_bin {
        // Higher base score for new bins to discourage opening them unless necessary
        // but scale it down if open_bins_count is low
        35.0 + (open_bins_count as f64 * 0.5)
    } else {
        post + fragmentation_penalty + lookahead_penalty + density_pressure
    };

    base_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Minimizing this is the Best-Fit strategy.
    let mut score = post_res;

    // Penalty for leaving "dead space" that is too small for common items (e.g., < 10).
    // This penalty is scaled by progress to become more conservative as the stream ends.
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item cannot fit in this bin, penalize the residual
    // to discourage creating a "near-miss" bin that leaves insufficient space for the next item.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += (next_item_size as f64 - post_res) * 1.5;
    }

    // Strategic choice for new bins:
    // If this is a new bin (bin_residual == bin_capacity), calculate if we should open it.
    // We penalize opening a new bin heavily unless the mean residual of current bins is high,
    // which suggests current bins are already fragmented.
    if bin_residual == bin_capacity {
        // High mean_residual means existing bins are mostly empty; prefer reusing them.
        // Low mean_residual means existing bins are tight; opening a new one is safer.
        score = 25.0 + (mean_residual * 0.5) - (progress * 5.0);
    } else {
        // Reward filling bins that are already "open" and have high occupancy (low residual).
        // This acts as a counter-weight to the Best-Fit preference.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

